contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public {
        require(caller != address(0), "zero caller");
        bool statusBefore = c.approvedToLog(caller); if (__ESBMC_reverted()) return;
        bool ret = c.logFraudDuringSetup(); if (__ESBMC_reverted()) return;
        bool statusAfter = c.approvedToLog(caller); if (__ESBMC_reverted()) return;
        assert(ret == statusBefore && statusAfter == statusBefore);
    }

    receive() external payable {}
}

